 env[L"ENSHROUDED_VRM_MODEL"]=s.model.wstring();env[L"ENSHROUDED_VRM_PROFILE"]=(s.root/L"Compatibility/profile.json").wstring();env[L"ENSHROUDED_VRM_CATALOG"]=(s.root/L"Compatibility/catalog.json").wstring();env[L"ENSHROUDED_VRM_VERIFIED_BUILD"]=wide(hash);env[L"ENSHROUDED_VRM_SHADERS"]=(runtime/L"shaders").wstring();env[L"ENSHROUDED_VRM_LOG"]=log.wstring();env[L"ENSHROUDED_VRM_CAPTURE_DIR"]=cache.wstring();env[L"ENSHROUDED_VRM_CAPTURE_FRAMES"]=L"none";env[L"ENSHROUDED_VRM_NATIVE_REPLACEMENT"]=L"1";env[L"ENSHROUDED_VRM_DEFER_RENDERING_PROOF"]=L"1";env[L"ENSHROUDED_VRM_GPU_SKINNING"]=L"1";env[L"ENSHROUDED_VRM_TOOL_SLOTS"]=L"1";env[L"ENSHROUDED_VRM_SPRING_BONES"]=s.springs?L"1":L"0";env[L"ENSHROUDED_VRM_DEBUG_OFFSET"]=L"0";env[L"SteamAppId"]=L"1203620";env[L"SteamGameId"]=L"1203620";return env;
