std::vector<wchar_t> environment_block(const Environment&env){std::vector<wchar_t> out;for(const auto&entry:env){need(!entry.first.empty()&&entry.first.find(L'\0')==std::wstring::npos&&entry.second.find(L'\0')==std::wstring::npos,"Invalid launch environment.");need(entry.first.find(L'=',entry.first.front()==L'='?1:0)==std::wstring::npos,"Invalid launch environment name.");out.insert(out.end(),entry.first.begin(),entry.first.end());out.push_back(L'=');out.insert(out.end(),entry.second.begin(),entry.second.end());out.push_back(0);need(out.size()<32760,"The launch environment is too large.");}out.push_back(0);if(env.empty())out.push_back(0);return out;}
